{ 
  uint8_t ret = LCD_ERROR;

  /* Default value for draw propriety */
  DrawProp.BackColor = 0xFFFF;
  DrawProp.pFont     = &Font24;
  DrawProp.TextColor = 0x0000;

  if(spfd5408_drv.ReadID() == SPFD5408_ID)
